fn rhehe_ravies_gq_fes03_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    if ctx.call(Function::CountItem, vec![Val::from(7840)])?.number()? > 0 {
        ctx.lines_as("Rhehe Ravies", args!["A flower!!", "Shall we proceed?"])?;
        ctx.next()?;
        if ctx
            .call(
                Function::GetGuildInfo,
                vec![ctx.call(Function::GetCharacterId, vec![Val::from(2)])?, Val::from(2)],
            )?
            .loosely_equals(&Val::from(1))
        {
            ctx.lines_as(
                "Rhehe Ravies",
                args!["Eeeeh, so young and yet you're a guild master? Your guildsmen must be jealous."],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Reumimi Ravies",
                args!["I'm not sure if you understand the uses for that flower, so I'll briefly explain."],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Reumimi Ravies",
                args![
                    "That flower has been passed down as a gift from the Valkyrie Wish Maiden herself.",
                    "It may be used to summon special monsters through summoners in special areas."
                ],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Rhehe Ravies",
                args![
                    "There are only two summoners in existence who are capable of using that flower.",
                    "One is me, and the other is my twin sister Reumimi."
                ],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Rhehe Ravies",
                args!["Twin sisters, but we do not have much alike, little fingers in front of you ..."],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Rhehe Ravies",
                args![
                    "..................................",
                    ".....Oops! I wasn't supposed to tell anyone..."
                ],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Rhehe Ravies",
                args!["... Hehehe, anyways let's move on.", "So do you wish to summon or not!?"],
            )?;
            ctx.next()?;
            'b1: {
                let subject1 = Val::from(runtime::select_values(ctx, &[Val::from("Do not summon:Summon")])?);
                let mut matched1 = false;
                let no_case1 = !subject1.loosely_equals(&Val::from(1)) && !subject1.loosely_equals(&Val::from(2));
                if !matched1 && subject1.loosely_equals(&Val::from(1)) {
                    matched1 = true;
                }
                if matched1 {
                    ctx.lines_as("Rhehe Ravies", args!["...*Cries*."])?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Rhehe Ravies",
                        args![
                            "If you've got no business with me, please don't start a conversation.",
                            "If it were my sister, she would've humiliated you for it."
                        ],
                    )?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
                if !matched1 && subject1.loosely_equals(&Val::from(2)) {
                    matched1 = true;
                }
                if matched1 {
                    break 'b1;
                }
            }
            ctx.lines_as("Rhehe Ravies", args!["Okay then, I'll explain a little about the summoning ritual.", "Here in Juno, the summoning ritual through the use of that flower will summon Valkyrie's Blessing and Valkyrie's Gift.", "The effects of the summoning ritual will last approximately one hour."])?;
            ctx.next()?;
            ctx.lines_as("Rhehe Ravies", args!["During the summoning ritual, continuous broadcasts will be made.", "It is a courtesy of the Valkyrie Wish Maiden, in order to unite adventurers from all over to participate in the festival."])?;
            ctx.next()?;
            ctx.lines_as("Rhehe Ravies", args!["Are you ready to begin the summoning ritual~?"])?;
            ctx.next()?;
            'b2: {
                let subject2 = Val::from(runtime::select_values(ctx, &[Val::from("No, not yet.:Yes! I'm ready!")])?);
                let mut matched2 = false;
                let no_case2 = !subject2.loosely_equals(&Val::from(1)) && !subject2.loosely_equals(&Val::from(2));
                if !matched2 && subject2.loosely_equals(&Val::from(1)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Rhehe Ravies", args!["You're not even ready, why bother talking to me?"])?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Rhehe Ravies",
                        args![
                            "Oh well, if you've got other things to do then I'll wait.",
                            "After all, that's also part of my job."
                        ],
                    )?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
                if !matched2 && subject2.loosely_equals(&Val::from(2)) {
                    matched2 = true;
                }
                if matched2 {
                    break 'b2;
                }
            }
            ctx.lines_as(
                "Rhehe Ravies",
                args!["Very well, then I will check for a reasonable time to begin the summoning ritual."],
            )?;
            ctx.next()?;
            if ctx.var("$@gqse_festival").get()? == 0 {
                ctx.lines_as("Rhehe Ravies", args!["Good! Now seems like a good time, so let's begin!"])?;
                ctx.call(Function::DelItem, vec![Val::from(7840), Val::from(1)])?;
                ctx.next()?;
                ctx.lines_as("Rhehe Ravies", args!["I hope you enjoy yourself!"])?;
                ctx.call(Function::DoNpcEvent, vec![Val::from("Rhehe Ravies#gq_fes03::OnStart")])?;
                ctx.call(
                    Function::Announce,
                    vec![
                        ((((Val::from("[") + ctx.call(Function::StrCharInfo, vec![Val::from(0)])?) + Val::from("] member of ["))
                            + ctx.call(
                                Function::GetGuildInfo,
                                vec![ctx.call(Function::GetCharacterId, vec![Val::from(2)])?, Val::from(0)],
                            )?)
                            + Val::from("] is summoning a 'Valkyrie's Present' in 'Rachel'.")),
                        ctx.constant("BC_ALL")?,
                        Val::from("0x70dbdb"),
                    ],
                )?;
                ctx.close_window()?;
                return Err(Stop::End);
            } else {
                ctx.lines_as("Rhehe Ravies", args!["*Cries*", "It doesn't seem like now is a good time."])?;
                ctx.next()?;
                ctx.lines_as("Rhehe Ravies", args!["Please try again later."])?;
                ctx.close_window()?;
                return Err(Stop::End);
            }
        } else {
            ctx.lines_as(
                "Rhehe Ravies",
                args!["...Seems like you're not in a worthy position for me to talk to?"],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Rhehe Ravies",
                args!["I don't know how you obtained that flower, but if you're not capable of leading others.. then you cannot continue."],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Rhehe Ravies",
                args!["Too tough?", "Well, what can you do, that's part of the job."],
            )?;
            ctx.close_window()?;
            return Err(Stop::End);
        }
    } else {
        ctx.lines_as("Rhehe Ravies", args!["Don't you have anything to give me to prove yourself?"])?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
}

